import java.io.*;
import java.sql.*;
import java.util.regex.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportExportServlet extends HttpServlet {

    private static final Pattern SAFE_TABLE_PATTERN = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("report_id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        // Validate report_id is numeric
        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report_id");
            return;
        }

        // Validate format
        if (format == null || !format.matches("(csv|json|xml)")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        Connection conn = null;
        try {
            conn = getDataSource().getConnection();

            // First, get the report metadata
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT table_name, display_name, owner_id FROM reports WHERE id = ?");
            metaStmt.setInt(1, Integer.parseInt(reportId));
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String tableName = metaRs.getString("table_name");
            String displayName = metaRs.getString("display_name");
            int ownerId = metaRs.getInt("owner_id");

            // Validate table name from DB is safe
            if (!SAFE_TABLE_PATTERN.matcher(tableName).matches()) {
                resp.sendError(500, "Invalid table configuration");
                return;
            }

            // Build the data query with optional filter
            String dataQuery = "SELECT * FROM " + tableName;
            if (filterExpr != null && !filterExpr.isEmpty()) {
                // The filter expression allows users to specify conditions
                // e.g., "status = 'active'" or "created_at > '2024-01-01'"
                dataQuery += " WHERE " + filterExpr;
            }

            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            // Export based on format
            resp.setHeader("Content-Disposition", 
                "attachment; filename=\"" + displayName + "." + format + "\"");

            if ("csv".equals(format)) {
                resp.setContentType("text/csv");
                exportCsv(dataRs, resp.getWriter());
            } else if ("json".equals(format)) {
                resp.setContentType("application/json");
                exportJson(dataRs, resp.getWriter());
            } else {
                resp.setContentType("application/xml");
                exportXml(dataRs, resp.getWriter());
            }

        } catch (SQLException e) {
            log("Database error in report export", e);
            resp.sendError(500, "Export failed");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private void exportCsv(ResultSet rs, PrintWriter out) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        for (int i = 1; i <= cols; i++) {
            if (i > 1) out.print(",");
            out.print(meta.getColumnName(i));
        }
        out.println();
        while (rs.next()) {
            for (int i = 1; i <= cols; i++) {
                if (i > 1) out.print(",");
                String val = rs.getString(i);
                out.print(val != null ? "\"" + val.replace("\"", "\"\"") + "\"" : "");
            }
            out.println();
        }
    }

    private void exportJson(ResultSet rs, PrintWriter out) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        out.println("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) out.println(",");
            out.print("  {");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) out.print(", ");
                out.print("\"" + meta.getColumnName(i) + "\": ");
                String val = rs.getString(i);
                out.print(val != null ? "\"" + val + "\"" : "null");
            }
            out.print("}");
            first = false;
        }
        out.println("\n]");
    }

    private void exportXml(ResultSet rs, PrintWriter out) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        out.println("<?xml version=\"1.0\"?>");
        out.println("<records>");
        while (rs.next()) {
            out.println("  <record>");
            for (int i = 1; i <= cols; i++) {
                String col = meta.getColumnName(i);
                String val = rs.getString(i);
                out.println("    <" + col + ">" + (val != null ? val : "") + "</" + col + ">");
            }
            out.println("  </record>");
        }
        out.println("</records>");
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportDB");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
